export type PolicyInput = EvaluationContext & { policy: BusinessPolicy; actionCatalog: ActionCatalog };

function approvalPending(events: CaseEvent[]): boolean {
  const approval = events.findLastIndex(e => e.type === 'DRAFT_APPROVED');
