    (event.type === 'CUSTOMER_CONFIRMED_NEXT_STEP' && event.actor === 'advisor' && event.simulated && event.payload.reviewedByAdvisor) ||
    (event.type === 'HUMAN_HANDOFF_CONFIRMED' && event.actor === 'advisor')
